function CODIFFERENTIAL(d[n][m], src[m], tgt[n]):
    for j in 0..m-1:
        for i in 0..n-1:
            delta[j][i] <- (1/src[j]) * d[i][j] * tgt[i]
    return delta            # m x n

function LAPLACIAN_UP(d, src, tgt):
    return CODIFFERENTIAL(d, src, tgt) * d      # m x m

function LAPLACIAN_DOWN(d, src, tgt):
    return d * CODIFFERENTIAL(d, src, tgt)      # n x n

